.ChangesReviewPage {
  width: 100%;
  padding: 0 36px 36px;
}
.ChangesReviewPage .header > div {
  display: flex;
  justify-content: space-between;
}
.ChangesReviewPage .headerTop .title {
  font-size: 18px;
  font-weight: 600;
  line-height: 24px;
}
.ChangesReviewPage .headerTop .commited {
  display: flex;
  text-align: right;
  color: var(--green-100per);
}
.ChangesReviewPage .headerTop .commited svg {
  margin-right: 10px;
}
.ChangesReviewPage .headerBottom {
  margin-top: 15px;
  align-items: start;
}
.ChangesReviewPage .headerBottom .subtitle {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  text-align: left;
}
.ChangesReviewPage .headerBottom .download {
  display: flex;
  color: var(--blue-100per);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  text-align: left;
  cursor: pointer;
}
.ChangesReviewPage .body .subtitle {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  text-align: left;
}
.ChangesReviewPage .body table {
  width: 100%;
  margin-top: 20px;
}
.ChangesReviewPage .body table th {
  border-bottom: 1px dotted var(--blue-120per);
  background: #fff !important;
  text-align: center !important;
}
.ChangesReviewPage .body table th:first-child {
  border-right: 1px dotted var(--blue-120per);
  background: #fff;
}
.ChangesReviewPage .body table tr td:first-child {
  border-right: 1px dotted var(--blue-120per);
  text-align: right;
  font-weight: bold;
}
.ChangesReviewPage .body table tr td input,
.ChangesReviewPage .body table tr td textarea {
  width: 100%;
  height: 70px;
  border: 1px solid var(--black-10per);
  border-radius: 4px;
  resize: none;
  line-height: 20px;
  padding: 10px;
  box-sizing: border-box;
}
.ChangesReviewPage .body table th,
.ChangesReviewPage .body table td {
  padding: 20px;
  text-align: left;
  width: fit-content;
  font-size: 14px;
  max-width: 250px;
  vertical-align: top;
}
.ChangesReviewPage .body table th:first-child,
.ChangesReviewPage .body table td:first-child {
  background: #fff;
  width: 160px;
  vertical-align: middle;
}
.ChangesReviewPage .body table th:last-child,
.ChangesReviewPage .body table td:last-child {
  vertical-align: middle;
}
.ChangesReviewPage .body table .stateDeleted {
  color: var(--red-text-100per);
}
.ChangesReviewPage .body table .stateChanged {
  color: var(--orange-75per);
}
