.ChangesReviewPage {
  width: 100%;
  padding: 0 36px;
}
.ChangesReviewPage .header > div {
  display: flex;
  justify-content: space-between;
  align-items: end;
}
.ChangesReviewPage .headerTop .title {
  font-size: 18px;
  font-weight: 600;
  line-height: 24px;
}
.ChangesReviewPage .headerTop .commited {
  display: flex;
  text-align: right;
  color: var(--green-100per);
}
.ChangesReviewPage .headerTop .commited svg {
  margin-right: 10px;
}
.ChangesReviewPage .headerBottom {
  margin-top: 15px;
}
.ChangesReviewPage .headerBottom .subtitle {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  text-align: left;
}
.ChangesReviewPage .headerBottom .download {
  display: flex;
  color: var(--blue-100per);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  text-align: left;
  cursor: pointer;
}
.ChangesReviewPage .body .subtitle {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  text-align: left;
}
.ChangesReviewPage .body table {
  margin-top: 20px;
}
.ChangesReviewPage .body table th, .ChangesReviewPage .body table td {
  padding: 20px;
  text-align: left;
  width: fit-content;
  font-size: 14px;
}
.ChangesReviewPage .body table .stateDeleted {
  color: var(--red-text-100per);
}
.ChangesReviewPage .body table .stateChanged {
  color: var(--orange-75per);
}
